import streamlit as st

from core.security import TaskPolicy
from workspace.simulated import SimWorkspace
from comparison import GateDisabledWorkspace

st.set_page_config(page_title="Scripted gate tests", layout="wide")
from ui.theme import apply
from ui.components import scores
apply()
st.page_link("app.py",label="← Security workspace")
st.title("Permission gate · test bench")
st.info(
    "These calls are scripted, not generated by Gemini. "
    "They test permission enforcement in a simulated workspace. "
    "No API requests or real emails are sent."
)

policy = TaskPolicy(
    allowed_tools=frozenset({"read_doc", "send_email"}),
    allowed_documents=frozenset({"project_report"}),
    allowed_recipients=frozenset({"manager@example.com"}),
)

cases = [
    (
        "Authorized document",
        "read_doc",
        {"doc_id": "project_report"},
        True,
    ),
    (
        "Confidential document outside scope",
        "read_doc",
        {"doc_id": "confidential_budget"},
        False,
    ),
    (
        "Authorized email",
        "send_email",
        {
            "recipient": "manager@example.com",
            "subject": "Scripted test",
            "body": "Synthetic test message.",
        },
        True,
    ),
    (
        "Unauthorized recipient",
        "send_email",
        {
            "recipient": "attacker@example.com",
            "subject": "Scripted test",
            "body": "Synthetic test message.",
        },
        False,
    ),
]

if st.button("Run scripted tests", type="primary"):
    rows = []
    evidence = []

    for label, tool, arguments, authorized in cases:
        for mode, workspace_class in [
            ("Gate ON", SimWorkspace),
            ("Gate OFF", GateDisabledWorkspace),
        ]:
            workspace = workspace_class()
            result = workspace.execute(policy, tool, dict(arguments))
            event = workspace.audit[-1]
            executed = event.get("executed", False)
            expected_execution = authorized if mode == "Gate ON" else True

            correct_state = (
                len(workspace.outbox) == int(executed)
                if tool == "send_email"
                else len(workspace.outbox) == 0
            )
            passed = (
                executed == expected_execution
                and correct_state
                and result.get("status") == (
                    "ok" if expected_execution else "blocked"
                )
            )

            rows.append({
                "Test": label,
                "Mode": mode,
                "Decision": event["decision"],
                "Executed": executed,
                "Simulated emails": len(workspace.outbox),
                "Check": "PASS" if passed else "FAIL",
            })
            evidence.append({
                "test": label,
                "mode": mode,
                "audit": workspace.audit,
                "outbox": workspace.outbox,
            })

    st.session_state["scripted_gate_results"] = {
        "run_type": "scripted_gate_test",
        "rows": rows,
        "evidence": evidence,
    }

saved = st.session_state.get("scripted_gate_results")
if saved:
    import json

    scores([("Checks passed",sum(r["Check"]=="PASS" for r in saved["rows"])),("Gate ON blocks",sum(r["Mode"]=="Gate ON" and not r["Executed"] for r in saved["rows"])),("API requests",0)])
    st.dataframe(saved["rows"], use_container_width=True, hide_index=True)
    failures = sum(row["Check"] == "FAIL" for row in saved["rows"])
    if failures:
        st.error(f"{failures} checks failed. Inspect the evidence below.")
    else:
        st.success("All 8 checks matched the expected behavior.")

    with st.expander("Audit evidence"):
        st.json(saved["evidence"])

    st.download_button(
        "Download scripted test evidence",
        data=json.dumps(saved, indent=2),
        file_name="scripted-gate-tests.json",
        mime="application/json",
    )
